import Foundation

/// A single DNS provider from Nginx Proxy Manager's bundled certbot DNS-plugin
/// catalog (`backend/certbot/dns-plugins.json`). `id` is exactly the value NPM
/// expects in `meta.dns_provider`; `credentialsTemplate` is the example INI block
/// NPM shows in its own UI, used here to pre-fill the credentials editor.
struct CertbotDNSProvider: Identifiable, Sendable, Hashable {
    let id: String
    let name: String
    let credentialsTemplate: String
}

/// The DNS-provider catalog, decoded once from an embedded copy of NPM's plugin
/// list. Embedded (rather than fetched) so it works offline and matches the NPM
/// version Pier was built against; refresh by re-running the generator in the PR.
enum CertbotDNSCatalog {
    static let providers: [CertbotDNSProvider] = decode()

    private struct Entry: Decodable {
        let name: String
        let credentials: String
    }

    private static func decode() -> [CertbotDNSProvider] {
        guard let data = Data(base64Encoded: encodedCatalog),
              let raw = try? JSONDecoder().decode([String: Entry].self, from: data) else {
            return []
        }
        return raw
            .map { CertbotDNSProvider(id: $0.key, name: $0.value.name, credentialsTemplate: $0.value.credentials) }
            .sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
    }

    /// Base64 of a minified `{ id: { name, credentials } }` JSON map (UTF-8).
    private static let encodedCatalog = ""
}
